func (c *Client) GetConfig() *Configuration {
	return c.cfg
}

type formFile struct {
	fileBytes    []byte
	fileName     string
	formFileName string
}

// prepareRequest build the request
func (c *Client) prepareRequest(
	ctx context.Context,
	path string, method string,
	postBody interface{},
	headerParams map[string]string,
	queryParams url.Values,
	formParams url.Values,
	formFiles []formFile) (localVarRequest *http.Request, err error) {

	var body *bytes.Buffer

	// Detect postBody type and post.
	if postBody != nil {
		// IsNil guards against a typed-nil pointer (e.g. an unset optional body)
		// boxed in the interface, which is != nil but would marshal to a literal
		// "null" body the API rejects with a 500.
		if !IsNil(postBody) {
			contentType := headerParams["Content-Type"]
			if contentType == "" {
				contentType = detectContentType(postBody)
				headerParams["Content-Type"] = contentType
			}

			body, err = setBody(postBody, contentType)
			if err != nil {
				return nil, err
			}
		}
	}

	// add form parameters and file if available.
	if strings.HasPrefix(headerParams["Content-Type"], "multipart/form-data") && len(formParams) > 0 || (len(formFiles) > 0) {
		if body != nil {
			return nil, errors.New("Cannot specify postBody and multipart form at the same time.")
		}
		body = &bytes.Buffer{}
		w := multipart.NewWriter(body)

		for k, v := range formParams {
			for _, iv := range v {
				if strings.HasPrefix(k, "@") { // file
					err = addFile(w, k[1:], iv)
					if err != nil {
						return nil, err
					}
				} else { // form value
					w.WriteField(k, iv)
				}
			}
		}
		for _, formFile := range formFiles {
			if len(formFile.fileBytes) > 0 && formFile.fileName != "" {
				w.Boundary()
				part, err := w.CreateFormFile(formFile.formFileName, filepath.Base(formFile.fileName))
				if err != nil {
					return nil, err
				}
				_, err = part.Write(formFile.fileBytes)
				if err != nil {
					return nil, err
				}
			}
		}

		// Set the Boundary in the Content-Type
		headerParams["Content-Type"] = w.FormDataContentType()

		// Set Content-Length
		headerParams["Content-Length"] = fmt.Sprintf("%d", body.Len())
		w.Close()
	}

	if strings.HasPrefix(headerParams["Content-Type"], "application/x-www-form-urlencoded") && len(formParams) > 0 {
		if body != nil {
			return nil, errors.New("Cannot specify postBody and x-www-form-urlencoded form at the same time.")
		}
		body = &bytes.Buffer{}
		body.WriteString(formParams.Encode())
		// Set Content-Length
		headerParams["Content-Length"] = fmt.Sprintf("%d", body.Len())
	}

	// Setup path and query parameters
	url, err := url.Parse(path)
	if err != nil {
		return nil, err
	}

	// Adding Query Param
	query := url.Query()
	for k, v := range queryParams {
		for _, iv := range v {
			query.Add(k, iv)
		}
	}

	// Encode the parameters.
	url.RawQuery = queryParamSplit.ReplaceAllStringFunc(query.Encode(), func(s string) string {
		pieces := strings.Split(s, "=")
		pieces[0] = queryDescape.Replace(pieces[0])
		return strings.Join(pieces, "=")
	})

	// Generate a new request
	if body != nil {
		localVarRequest, err = http.NewRequestWithContext(ctx, method, url.String(), body)
	} else {
		localVarRequest, err = http.NewRequestWithContext(ctx, method, url.String(), nil)
	}
	if err != nil {
		return nil, err
	}

	// add header parameters, if any
	if len(headerParams) > 0 {
		headers := http.Header{}
		for h, v := range headerParams {
			headers[h] = []string{v}
		}
		localVarRequest.Header = headers
	}

	// Add the user agent to the request.
	localVarRequest.Header.Add("User-Agent", c.cfg.UserAgent)

	return localVarRequest, nil
}

func (c *Client) decode(v interface{}, b []byte, contentType string) (err error) {
	if len(b) == 0 {
		return nil
	}
	if s, ok := v.(*string); ok {
		*s = string(b)
		return nil
	}
	if f, ok := v.(*os.File); ok {
		f, err = ioutil.TempFile("", "HttpClientFile")
		if err != nil {
			return
		}
		_, err = f.Write(b)
		if err != nil {
			return
		}
		_, err = f.Seek(0, io.SeekStart)
		return
	}
	if f, ok := v.(**os.File); ok {
		*f, err = ioutil.TempFile("", "HttpClientFile")
		if err != nil {
			return
		}
		_, err = (*f).Write(b)
		if err != nil {
			return
		}
		_, err = (*f).Seek(0, io.SeekStart)
		return
	}
	if xmlCheck.MatchString(contentType) {
		if err = xml.Unmarshal(b, v); err != nil {
			return err
		}
		return nil
	}
	if jsonCheck.MatchString(contentType) {
		if actualObj, ok := v.(interface{ GetActualInstance() interface{} }); ok { // oneOf, anyOf schemas
			if unmarshalObj, ok := actualObj.(interface{ UnmarshalJSON([]byte) error }); ok { // make sure it has UnmarshalJSON defined
				if err = unmarshalObj.UnmarshalJSON(b); err != nil {
					return err
				}
			} else {
				return errors.New("Unknown type with GetActualInstance but no unmarshalObj.UnmarshalJSON defined")
			}
		} else if err = json.Unmarshal(b, v); err != nil { // simple model
			return err
		}
		return nil
	}
	return errors.New("undefined response type")
}

// Add a file to the multipart request
func addFile(w *multipart.Writer, fieldName, path string) error {
	file, err := os.Open(filepath.Clean(path))
	if err != nil {
		return err
	}
	err = file.Close()
	if err != nil {
		return err
	}

	part, err := w.CreateFormFile(fieldName, filepath.Base(path))
	if err != nil {
		return err
	}
	_, err = io.Copy(part, file)

	return err
}

// Set request body from an interface{}
func setBody(body interface{}, contentType string) (bodyBuf *bytes.Buffer, err error) {
	if bodyBuf == nil {
		bodyBuf = &bytes.Buffer{}
	}

	if reader, ok := body.(io.Reader); ok {
		_, err = bodyBuf.ReadFrom(reader)
	} else if fp, ok := body.(*os.File); ok {
		_, err = bodyBuf.ReadFrom(fp)
	} else if b, ok := body.([]byte); ok {
		_, err = bodyBuf.Write(b)
	} else if s, ok := body.(string); ok {
		_, err = bodyBuf.WriteString(s)
	} else if s, ok := body.(*string); ok {
		_, err = bodyBuf.WriteString(*s)
	} else if jsonCheck.MatchString(contentType) {
		err = json.NewEncoder(bodyBuf).Encode(body)
	} else if xmlCheck.MatchString(contentType) {
		err = xml.NewEncoder(bodyBuf).Encode(body)
	}

	if err != nil {
		return nil, err
	}

	if bodyBuf.Len() == 0 {
		err = fmt.Errorf("invalid body type %s\n", contentType)
		return nil, err
	}
	return bodyBuf, nil
}

// detectContentType method is used to figure out `Request.Body` content type for request header
func detectContentType(body interface{}) string {
	contentType := "text/plain; charset=utf-8"
	kind := reflect.TypeOf(body).Kind()

	switch kind {
	case reflect.Struct, reflect.Map, reflect.Ptr:
		contentType = "application/json; charset=utf-8"
	case reflect.String:
		contentType = "text/plain; charset=utf-8"
	default:
		if b, ok := body.([]byte); ok {
			contentType = http.DetectContentType(b)
		} else if kind == reflect.Slice {
			contentType = "application/json; charset=utf-8"
		}
	}

	return contentType
}

// Ripped from https://github.com/gregjones/httpcache/blob/master/httpcache.go
type cacheControl map[string]string

func parseCacheControl(headers http.Header) cacheControl {
	cc := cacheControl{}
	ccHeader := headers.Get("Cache-Control")
	for _, part := range strings.Split(ccHeader, ",") {
		part = strings.Trim(part, " ")
		if part == "" {
			continue
		}
		if strings.ContainsRune(part, '=') {
			keyval := strings.Split(part, "=")
			cc[strings.Trim(keyval[0], " ")] = strings.Trim(keyval[1], ",")
		} else {
			cc[part] = ""
		}
	}
	return cc
}

// CacheExpires helper function to determine remaining time before repeating a request.
func CacheExpires(r *http.Response) time.Time {
	// Figure out when the cache expires.
	var expires time.Time
	now, err := time.Parse(time.RFC1123, r.Header.Get("date"))
	if err != nil {
		return time.Now()
	}
	respCacheControl := parseCacheControl(r.Header)

	if maxAge, ok := respCacheControl["max-age"]; ok {
		lifetime, err := time.ParseDuration(maxAge + "s")
		if err != nil {
			expires = now
		} else {
			expires = now.Add(lifetime)
		}
	} else {
		expiresHeader := r.Header.Get("Expires")
		if expiresHeader != "" {
			expires, err = time.Parse(time.RFC1123, expiresHeader)
			if err != nil {
				expires = now
			}
		}
	}
	return expires
}

func strlen(s string) int {
	return utf8.RuneCountInString(s)
}

type ErrorResponseItem struct {
	Context any    `json:"context"`
	Message string `json:"message"`
}

// ErrorResponse - Similar to Python's ErrorResponse.
type ErrorResponse struct {
	StatusCode int
	Errors     []ErrorResponseItem
	Headers    http.Header
}

func (e ErrorResponse) Error() string {
	return fmt.Sprintf("status_code: %d, errors: %v", e.StatusCode, e.Errors)
}

func (e ErrorResponse) ToDict() map[string]interface{} {
	return map[string]interface{}{
		"status_code": e.StatusCode,
		"errors":      e.Errors,
		"headers":     e.Headers,
	}
}

// GenericOpenAPIError Provides access to the body, error and model on returned errors.
type GenericOpenAPIError struct {
	body  []byte
	error string
	model interface{}
}

func (e GenericOpenAPIError) Error() string {
	return e.error
}

// Body returns the raw bytes of the response
func (e GenericOpenAPIError) Body() []byte {
	return e.body
}

// Model returns the unpacked model of the error
func (e GenericOpenAPIError) Model() interface{} {
	return e.model
}

// format error message using title and detail when model implements rfc7807
func formatErrorMessage(status string, v interface{}) string {
	str := ""
	metaValue := reflect.ValueOf(v).Elem()

	field := metaValue.FieldByName("Title")
	if field != (reflect.Value{}) {
		str = fmt.Sprintf("%s", field.Interface())
	}

	field = metaValue.FieldByName("Detail")
	if field != (reflect.Value{}) {
		str = fmt.Sprintf("%s (%s)", str, field.Interface())
	}

	// status title (detail)
	return strings.TrimSpace(fmt.Sprintf("%s %s", status, str))
}

// Closes client
func (c *Client) Close() {
	if c.cfg.Authentificator != nil {
		c.cfg.Authentificator.Close(context.Background(), *c.AuthorizationAPI)
	}
}

// Generic API call
func (c *Client) Call(ctx context.Context, endpoint, method string, query map[string]interface{}, body interface{}) (interface{}, *http.Response, error) {
	descriptorKey := upperCaseFirst(method) + " /api/2.35" + endpoint
	descriptor, ok := endpointToDescriptor[descriptorKey]
	if !ok {
		return nil, nil, fmt.Errorf("%s %s is not supported by the client", method, endpoint)
	}
	api := reflect.ValueOf(*c).FieldByName(descriptor.api)
	if !api.IsValid() {
		return nil, nil, fmt.Errorf("api %s not found", descriptor.api)
	}

	apiResourceMethod := api.MethodByName(descriptor.resourceFactory)
	if !apiResourceMethod.IsValid() {
		return nil, nil, fmt.Errorf("failed to create an api resource request %s for api %s - does not exist", descriptor.resourceFactory, descriptor.api)
	}
	ret := apiResourceMethod.Call([]reflect.Value{reflect.ValueOf(ctx)})
	if len(ret) != 1 {
		return nil, nil, fmt.Errorf("failed to create an api resource request %s for api %s - not supported by the client", descriptor.resourceFactory, descriptor.api)
	}
	apiResourceRequest := ret[0]

	apiResourceRequest, err := setQueryParams(apiResourceRequest, query)
	if err != nil {
		return nil, nil, err
	}
	apiResourceRequest, err = setBodyParams(apiResourceRequest, body, descriptor)
	if err != nil {
		return nil, nil, err
	}

	apiResourceRequestExecute := apiResourceRequest.MethodByName("Execute")
	if !apiResourceRequestExecute.IsValid() {
		return nil, nil, fmt.Errorf("method Execute not found on %s fro api %s", descriptor.resourceFactory, descriptor.api)
	}
	ret = apiResourceRequestExecute.Call([]reflect.Value{})

	var errUntyped interface{}
	var response interface{}
	errUntyped = ret[len(ret)-1].Interface()
	if errUntyped == nil && len(ret) == 3 {
		if ret[0].Kind() == reflect.Ptr {
			response = ret[0].Elem().Interface()
		} else {
			response = ret[0].Interface()
		}
	}
	if errUntyped != nil {
		if err, ok := errUntyped.(error); ok {
			return nil, nil, err
		} else {
			return nil, nil, fmt.Errorf("failed to execute API call %s %s: %v", method, endpoint, errUntyped)
		}
	}

	return response, ret[len(ret)-2].Interface().(*http.Response), nil
}

func setQueryParams(apiResourceRequest reflect.Value, query map[string]interface{}) (reflect.Value, error) {
	for key, value := range query {
		querySetterName := pascalCase(key, "_")
		querySetter := apiResourceRequest.MethodByName(querySetterName)
		if !querySetter.IsValid() {
			return apiResourceRequest, fmt.Errorf("query setter %s not found on %s", querySetterName, apiResourceRequest.Type().Name())
		}
		expectedType := querySetter.Type().In(0)
		convertedValue, err := convertValue(value, expectedType)
		if err != nil {
			return apiResourceRequest, fmt.Errorf("failed to convert value for query param %s: %w", key, err)
		}
		ret := querySetter.Call([]reflect.Value{convertedValue})
		if len(ret) != 1 {
			return apiResourceRequest, fmt.Errorf("query setter %s returned unexpected number of output parameters on %s", querySetterName, apiResourceRequest.Type().Name())
		}
		apiResourceRequest = ret[0]
	}

	return apiResourceRequest, nil
}

func createBodyParams(bodyParamType reflect.Type, body map[string]interface{}) (reflect.Value, error) {
	bodyParam := reflect.New(bodyParamType)
	for key, value := range body {
		bodySetterName := "Set" + pascalCase(key, "_")
		bodySetter := bodyParam.MethodByName(bodySetterName)
		if !bodySetter.IsValid() {
			return bodyParam, fmt.Errorf("body setter %s not found on %s", bodySetterName, bodyParamType.Name())
		}
		expectedType := bodySetter.Type().In(0)
		convertedValue, err := convertValue(value, expectedType)
		if err != nil {
			return bodyParam, fmt.Errorf("failed to convert value for %s: %w", bodySetterName, err)
		}
		_ = bodySetter.Call([]reflect.Value{convertedValue})
	}

	return bodyParam.Elem(), nil
}

func convertValue(value interface{}, targetType reflect.Type) (reflect.Value, error) {
	valueReflect := reflect.ValueOf(value)

	if valueReflect.Type() == targetType {
		return valueReflect, nil
	}

	if valueReflect.Kind() == reflect.Float64 && targetType.Kind() == reflect.Int64 {
		return reflect.ValueOf(int64(value.(float64))), nil
	}

	if valueReflect.Kind() == reflect.Slice && targetType.Kind() == reflect.Slice {
		sliceLen := valueReflect.Len()
		newSlice := reflect.MakeSlice(targetType, sliceLen, sliceLen)

		for i := 0; i < sliceLen; i++ {
			elem := valueReflect.Index(i).Interface()
			convertedElem, err := convertValue(elem, targetType.Elem())
			if err != nil {
				return reflect.Value{}, fmt.Errorf("failed to convert slice element at index %d: %w", i, err)
			}
			newSlice.Index(i).Set(convertedElem)
		}

		return newSlice, nil
	}

	if valueReflect.Type().ConvertibleTo(targetType) {
		return valueReflect.Convert(targetType), nil
	}

	return reflect.Value{}, fmt.Errorf("cannot convert %v (type %s) to %s", value, valueReflect.Type(), targetType)
}

func setBodyParams(apiResourceRequest reflect.Value, body interface{}, descriptor opDescriptor) (reflect.Value, error) {
	setBodyMethod := apiResourceRequest.MethodByName(descriptor.bodySetter)
	if !setBodyMethod.IsValid() {
		if body != nil {
			return apiResourceRequest, fmt.Errorf("provided body parameters, but resource %s doesn't support body", descriptor.resourceFactory)
		}
		return apiResourceRequest, nil
	}

	bodyParamType := setBodyMethod.Type().In(0)
	var bodyParamValue reflect.Value
	if bodyParamType.Kind() == reflect.Array || bodyParamType.Kind() == reflect.Slice {
		bodyParamType = bodyParamType.Elem()
		arrayBody, ok := body.([]map[string]interface{})
		if !ok {
			return apiResourceRequest, fmt.Errorf("body must be []map[string]interface{}")
		}
		sliceType := reflect.SliceOf(bodyParamType)
		bodyParamValue = reflect.MakeSlice(sliceType, len(arrayBody), len(arrayBody))
		for i, singleBody := range arrayBody {
			val, err := createBodyParams(bodyParamType, singleBody)
			if err != nil {
				return apiResourceRequest, err
			}
			bodyParamValue.Index(i).Set(val)
		}
	} else if bodyParamType.Kind() == reflect.Struct {
		singleBody, ok := body.(map[string]interface{})
		if !ok {
			return apiResourceRequest, fmt.Errorf("body must be map[string]interface{}")
		}
		var err error
		bodyParamValue, err = createBodyParams(bodyParamType, singleBody)
		if err != nil {
			return apiResourceRequest, err
		}
	} else {
		bodyParamValue = reflect.ValueOf(body)
	}
	ret := setBodyMethod.Call([]reflect.Value{bodyParamValue})
	if len(ret) != 1 {
		return apiResourceRequest, fmt.Errorf("set body method %s returned unexpected number of output parameters", descriptor.bodySetter)
	}
	return ret[0], nil
}

func upperCaseFirst(s string) string {
	if s == "" {
		return s
	}
	runes := []rune(strings.ToLower(s))
	runes[0] = unicode.ToUpper(runes[0])
	return string(runes)
}

func pascalCase(s, sep string) string {
	parts := strings.Split(s, sep)
	for inx, part := range parts {
		parts[inx] = upperCaseFirst(part)
	}
	return strings.Join(parts, "")
}
